// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  // spec: specs/hal-engine-conversation-list/spec.md#3
  it('accepts a list_sessions cursor and strips its unknown userId', () => {
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        userId: 'another-user',
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 10,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
    });
  });

  it('rejects malformed list_sessions pagination fields with field-specific errors', () => {
    const results = [
      {type: 'list_sessions', limit: '10'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
    ].map(payload => validateMessage(payload));

    expect(results).toEqual([
      {valid: false, error: expect.stringMatching(/limit|before/)},
      {valid: false, error: expect.stringMatching(/limit|before/)},
      {valid: false, error: expect.stringMatching(/limit|before/)},
      {valid: false, error: expect.stringMatching(/limit|before/)},
      {valid: false, error: expect.stringMatching(/limit|before/)},
      {valid: false, error: expect.stringMatching(/limit|before/)},
    ]);
  });

  // spec: specs/hal-engine-conversation-list/spec.md#4
  it('rejects a list_sessions limit above the protocol maximum', () => {
    expect(validateMessage({type: 'list_sessions', limit: 201})).toEqual({
      valid: false,
      error: 'list_sessions limit must be between 1 and 200',
    });
  });

  // specs/hal-engine-websocket-protocol/spec.md#12
  it('accepts a list_conversations frame with an ISO cursor', () => {
    expect(
      validateMessage({
        type: 'list_conversations',
        limit: 20,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_conversations',
        limit: 20,
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      },
    });
  });
});
